namespace App\Jobs;

use App\Models\MediaAsset;
use Illuminate\Bus\Queueable;
use Illuminate\Contracts\Queue\ShouldQueue;
use Illuminate\Foundation\Bus\Dispatchable;
use Illuminate\Queue\InteractsWithQueue;
use Illuminate\Queue\SerializesModels;
use Illuminate\Support\Facades\Storage;
use Illuminate\Auth\Access\AuthorizationException;

class TranscodeMediaJob implements ShouldQueue
{
    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;

    public function __construct(public int $tenantId, public int $assetId, public string $filename)
    {
    }

    public function handle(): void
    {
        $asset = MediaAsset::where('tenant_id', $this->tenantId)->findOrFail($this->assetId);
        $safePath = "tenants/{$this->tenantId}/transcoded/{$this->filename}";
        $transcoded = $this->encodeVideo($asset->raw_s3_url);
        Storage::disk('s3')->put($safePath, $transcoded);
    }
}
